package structural.proxy.sample;

public interface IImage {
    void display();
}

package structural.proxy.sample;

public class Main {
    public static void main(String[] args) {
        IImage image = new ProxyImage("photo.png");
        System.out.println("Image object created, nothing loaded yet.");
        image.display(); // loads from disk now
        image.display(); // reuses already-loaded RealImage


        IImage protectedImageAdmin = new ProtectedImageProxy("photo.png", "ADMIN");
        protectedImageAdmin.display();

        IImage protectedImageEmp = new ProtectedImageProxy("photo.png", "EMP");
        protectedImageEmp.display();

    }
}

package structural.proxy.sample;

public class ProtectedImageProxy implements IImage {     
    private final String filename;
    private final String userRole;
    private RealImage realImage;

    public ProtectedImageProxy(String filename, String userRole) {
        this.filename = filename;
        this.userRole = userRole;
    }

    @Override
    public void display() {
        if (!"ADMIN".equals(userRole)) {
            System.out.println( "Access denied. Only ADMIN can view this image." );
            return;
        } 
        if (realImage == null) {
            realImage = new RealImage(filename);
        } 
        realImage.display();
    }
}

package structural.proxy.sample;

// Virtual proxy — defers the expensive RealImage construction until display() is actually called.
public class ProxyImage implements IImage {
    private final String filename;
    private RealImage realImage;

    public ProxyImage(String filename) {
        this.filename = filename;
    }

    // This can be created using singleton pattern as well, 
    // but for simplicity, we are creating a new instance of RealImage every time display() is called.
    @Override
    public void display() {
        if (realImage == null) {
            realImage = new RealImage(filename);
        }
        realImage.display();
    }
}

package structural.proxy.sample;

public class RealImage implements IImage {
    private final String filename;

    public RealImage(String filename) {
        this.filename = filename;
        loadFromDisk();
    }

    private void loadFromDisk() {
        System.out.println("Loading " + filename + " from disk...");
    }

    @Override
    public void display() {
        System.out.println("Displaying " + filename);
    }
}

